INSERT INTO "rule_set" ("id", "organization_id", "status", "version", "rules", "tests", "summary", "published_at", "published_by", "updated_by") VALUES
  ('rs_demo_v1', 'org_demo', 'published', 1, '[{"id":"r-reroute","name":"Reroute: same-country sale from other EU stock","note":"Matches spreadsheet v3. Miranda confirmed (14 Oct) this blocks consumer sales too, as the client has no local VAT registration.","signoff":false,"when":{"origin":["OTHER"],"dispatchIsDest":true},"then":{"warning":"Stock in {dispatch} can''t be sold for delivery within {dispatch}: the client has no VAT registration there. Move the goods through the Netherlands warehouse first.","needsVat":false,"level":"block","entity":"","code":"REROUTE VIA NL REQUIRED","rate":{"kind":"none"},"invoice":"DO NOT INVOICE: Goods must be rerouted through the Netherlands warehouse to comply with local storage tax rules."}},{"id":"r-export","name":"Export outside the UK and EU","note":"Matches spreadsheet v3.","signoff":false,"when":{"destZone":["ROW"]},"then":{"warning":"CRITICAL EXPORT CHECK: Fulfill this order from UK stock where possible to avoid EU paper registration customs blockages.","needsVat":false,"level":"ok","entity":"UK","code":"0% Export","rate":{"kind":"fixed","value":0},"invoice":"Zero-Rated Export – Out of Scope of UK/EU VAT. Proof of export required for tax records."}},{"id":"r-uk-domestic","name":"UK stock delivered in the UK","note":"Matches spreadsheet v3. The client is established in the UK.","signoff":false,"when":{"origin":["UK"],"destZone":["UK"]},"then":{"warning":"Standard UK Domestic transaction rules apply.","needsVat":false,"level":"ok","entity":"UK","code":"20% UK VAT","rate":{"kind":"dest"},"invoice":"Standard Domestic Supply - UK VAT charged at the statutory rate."}},{"id":"r-eu-uk","name":"EU stock delivered in the UK","note":"Matches spreadsheet v3. Miranda (14 Oct): the client owns the goods on import into the UK, so this is a UK sale. Open point: assumes the client always imports the goods itself.","signoff":true,"when":{"origin":["NL","OTHER"],"destZone":["UK"]},"then":{"warning":"NOTE: Import VAT and customs clearance are handled internally by our firm. Charge standard 20% UK domestic VAT to the buyer.","needsVat":false,"level":"ok","entity":"UK","code":"20% UK VAT","rate":{"kind":"dest"},"invoice":"UK Domestic Supply following importation - UK VAT charged at the statutory rate."}},{"id":"r-uk-eu-b2b","name":"UK stock to an EU business","note":"Differs from spreadsheet v3: its formula gives intra-community supply or triangulation here, but its own warning and rule table say 0% UK export. Open point: v3 says invoice from the NL company; confirm.","signoff":true,"when":{"origin":["UK"],"destZone":["EU","NL"],"type":["B2B"]},"then":{"warning":"CRITICAL POST-BREXIT WARNING: Direct transport from UK into the EU constitutes an import. Local customs duties and Import VAT are fully applicable at the border.","needsVat":false,"level":"ok","entity":"NL","code":"0% UK Export","rate":{"kind":"fixed","value":0},"invoice":"Zero-Rated UK Export. Import VAT and local customs duties are payable by the importer/consignee at the border prior to delivery."}},{"id":"r-uk-eu-ioss","name":"UK stock to an EU consumer, parcel €150 or less","note":"Differs from spreadsheet v3: its formula uses OSS wording. Miranda agreed (13 Oct) this is IOSS for parcels up to €150; the client uses IOSS. Invoice wording and invoicing company to confirm.","signoff":true,"when":{"origin":["UK"],"destZone":["EU","NL"],"type":["B2C"],"value":["low"]},"then":{"warning":"Ship from EU stock if you can. If this order has to leave from the UK, charge {dest} VAT under IOSS and give the carrier your IOSS number for the customs declaration.","needsVat":false,"level":"warn","entity":"NL","code":"IOSS","rate":{"kind":"dest"},"invoice":"Distance sale of imported goods – {dest} VAT charged at {rate} under IOSS."}},{"id":"r-uk-eu-import","name":"UK stock to an EU consumer, parcel over €150","note":"Differs from spreadsheet v3: its formula uses OSS wording. Above €150 IOSS can''t be used, so this is a 0% UK export with import VAT at the border. Invoice wording and invoicing company to confirm.","signoff":true,"when":{"origin":["UK"],"destZone":["EU","NL"],"type":["B2C"],"value":["high"]},"then":{"warning":"Ship from EU stock if you can. Above €150 IOSS can''t be used, so import VAT ({destRate}) and any duty are collected at the border unless you ship duties paid (DDP).","needsVat":false,"level":"warn","entity":"NL","code":"0% UK Export","rate":{"kind":"fixed","value":0},"invoice":"Zero-Rated UK Export. Import VAT and duty are payable on import into {dest}."}},{"id":"r-nl-rc","name":"NL stock to a business, delivered in NL","note":"Differs from spreadsheet v3: its formula skips the reverse charge when goods ship from the Netherlands and gives intra-community supply or triangulation. Miranda confirmed (13 Oct) the reverse charge applies to any business delivery in NL because of the paper registration. She''s checking the \"Section 1e\" reference.","signoff":true,"when":{"origin":["NL"],"destZone":["NL"],"type":["B2B"]},"then":{"warning":"","needsVat":true,"level":"ok","entity":"NL","code":"0% NL RC","rate":{"kind":"fixed","value":0},"invoice":"VAT Reversed - Section 1e Dutch Turnover Tax Act (Non-established supplier)"}},{"id":"r-nl-b2c","name":"NL stock to a Dutch consumer","note":"Same 21% as spreadsheet v3, but v3 uses OSS wording for what is a sale within the Netherlands, so the wording says domestic supply.","signoff":false,"when":{"origin":["NL"],"destZone":["NL"],"type":["B2C"]},"then":{"warning":"Standard B2C Rules Apply. Ensure destination address matches consumer location.","needsVat":false,"level":"ok","entity":"NL","code":"Standard NL VAT","rate":{"kind":"dest"},"invoice":"Dutch domestic supply – NL VAT charged at {rate}."}},{"id":"r-other-nl","name":"Other EU stock to a business in NL","note":"Matches spreadsheet v3. Reverse-charged because of the client''s paper NL registration. Miranda is checking the \"Section 1e\" reference.","signoff":true,"when":{"origin":["OTHER"],"destZone":["NL"],"type":["B2B"]},"then":{"warning":"","needsVat":true,"level":"ok","entity":"NL","code":"0% NL RC","rate":{"kind":"fixed","value":0},"invoice":"VAT Reversed - Section 1e Dutch Turnover Tax Act (Non-established supplier)"}},{"id":"r-nonEU-novat","name":"Non-EU customer without a verified EU VAT number","note":"Differs from spreadsheet v3: its tax code says triangulation and its warning tells the user to switch to B2C. Miranda confirmed (13 Oct): without a valid EU VAT number it''s a consumer sale at the delivery country''s rate, so the app does that automatically.","signoff":false,"when":{"origin":["NL","OTHER"],"destZone":["EU"],"type":["B2B"],"custZone":["UK","ROW"],"vies":["unchecked","unavailable"]},"then":{"warning":"The customer is based in {cust} and has no verified EU VAT number, so this is treated as a consumer sale. If they give you a valid {dest} VAT number for the receiving party, check it with VIES: the sale can then be zero-rated.","needsVat":false,"level":"ok","entity":"NL","code":"OSS Destination Rate","rate":{"kind":"dest"},"invoice":"EU OSS B2C Distance Selling – VAT charged at local destination rate for {dest}."}},{"id":"r-triangulation","name":"Triangulation","note":"Differs from spreadsheet v3: its formula still triggers triangulation when the customer''s country differs from the delivery country. Miranda confirmed (14 Oct) it''s when the despatch country, NL and the delivery country are all different. Open point: does it still apply when the customer is based in a different country from the delivery country?","signoff":true,"when":{"origin":["OTHER"],"destZone":["EU"],"type":["B2B"]},"then":{"warning":"There must be exactly one physical cross-border movement of goods. The transport must be arranged and paid for by either the supplier (despatch country) or the intermediary (your business).","needsVat":true,"level":"ok","entity":"NL","code":"0% EU Triangulation","rate":{"kind":"fixed","value":0},"invoice":"VAT Reverse Charge – Simplified Triangulation Rule Applies. Final customer self-accounts for local acquisition VAT."}},{"id":"r-ics","name":"Intra-community supply from NL stock","note":"Differs from spreadsheet v3: its formula calls this triangulation when the customer''s country differs from the delivery country. Goods leaving the Netherlands can''t be triangulation under Miranda''s 14 Oct answer, so this is a plain 0% intra-community supply. Open point: confirm for customers based in a third EU country.","signoff":true,"when":{"origin":["NL"],"destZone":["EU"],"type":["B2B"]},"then":{"warning":"","needsVat":true,"level":"ok","entity":"NL","code":"0% Intra-Community Supply","rate":{"kind":"fixed","value":0},"invoice":"Zero-Rated Intra-Community Supply - Customer accounts for Acquisition VAT in destination country."}},{"id":"r-oss","name":"EU stock to an EU consumer (OSS)","note":"Matches spreadsheet v3.","signoff":false,"when":{"origin":["NL","OTHER"],"destZone":["EU","NL"],"type":["B2C"]},"then":{"warning":"Standard B2C Rules Apply. Ensure destination address matches consumer location.","needsVat":false,"level":"ok","entity":"NL","code":"OSS Destination Rate","rate":{"kind":"dest"},"invoice":"EU OSS B2C Distance Selling – VAT charged at local destination rate for {dest}."}}]'::jsonb, '[{"id":"t01","label":"UK stock to UK business","inp":{"dispatch":"UK","dest":"UK","cust":"UK","type":"B2B","vies":"unchecked","value":"low"},"expect":{"code":"20% UK VAT","rate":20,"entity":"UK"}},{"id":"t02","label":"UK stock to UK consumer","inp":{"dispatch":"UK","dest":"UK","cust":"UK","type":"B2C","vies":"unchecked","value":"low"},"expect":{"code":"20% UK VAT","rate":20,"entity":"UK"}},{"id":"t03","label":"NL stock to the UK, German customer","inp":{"dispatch":"Netherlands","dest":"UK","cust":"Germany","type":"B2B","vies":"unchecked","value":"low"},"expect":{"code":"20% UK VAT","rate":20,"entity":"UK"}},{"id":"t04","label":"French stock to a UK consumer","inp":{"dispatch":"France","dest":"UK","cust":"UK","type":"B2C","vies":"unchecked","value":"low"},"expect":{"code":"20% UK VAT","rate":20}},{"id":"t05","label":"UK stock to rest of world","inp":{"dispatch":"UK","dest":"ROW","cust":"ROW","type":"B2B","vies":"unchecked","value":"low"},"expect":{"code":"0% Export","entity":"UK"}},{"id":"t06","label":"Spanish stock to rest of world","inp":{"dispatch":"Spain","dest":"ROW","cust":"ROW","type":"B2B","vies":"unchecked","value":"low"},"expect":{"code":"0% Export","entity":"UK"}},{"id":"t07","label":"UK stock to Irish business","inp":{"dispatch":"UK","dest":"Ireland","cust":"Ireland","type":"B2B","vies":"unchecked","value":"low"},"expect":{"code":"0% UK Export","rate":0}},{"id":"t08","label":"UK stock to German consumer, €150 or less","inp":{"dispatch":"UK","dest":"Germany","cust":"Germany","type":"B2C","vies":"unchecked","value":"low"},"expect":{"code":"IOSS","rate":19,"level":"warn"}},{"id":"t09","label":"UK stock to German consumer, over €150","inp":{"dispatch":"UK","dest":"Germany","cust":"Germany","type":"B2C","vies":"unchecked","value":"high"},"expect":{"code":"0% UK Export","rate":0,"level":"warn"}},{"id":"t10","label":"NL stock to Dutch business, VAT no. verified","inp":{"dispatch":"Netherlands","dest":"Netherlands","cust":"Netherlands","type":"B2B","vies":"valid","value":"low"},"expect":{"code":"0% NL RC","level":"ok","entity":"NL"}},{"id":"t11","label":"NL stock delivered in NL to a German business","inp":{"dispatch":"Netherlands","dest":"Netherlands","cust":"Germany","type":"B2B","vies":"valid","value":"low"},"expect":{"code":"0% NL RC"}},{"id":"t12","label":"NL stock to Dutch consumer","inp":{"dispatch":"Netherlands","dest":"Netherlands","cust":"Netherlands","type":"B2C","vies":"unchecked","value":"low"},"expect":{"code":"Standard NL VAT","rate":21}},{"id":"t13","label":"French stock to Dutch business","inp":{"dispatch":"France","dest":"Netherlands","cust":"Netherlands","type":"B2B","vies":"valid","value":"low"},"expect":{"code":"0% NL RC"}},{"id":"t14","label":"French stock to Dutch consumer","inp":{"dispatch":"France","dest":"Netherlands","cust":"Netherlands","type":"B2C","vies":"unchecked","value":"low"},"expect":{"code":"OSS Destination Rate","rate":21}},{"id":"t15","label":"NL stock to German business, VAT no. verified","inp":{"dispatch":"Netherlands","dest":"Germany","cust":"Germany","type":"B2B","vies":"valid","value":"low"},"expect":{"code":"0% Intra-Community Supply","level":"ok","entity":"NL"}},{"id":"t16","label":"NL stock to German business, VAT no. not checked","inp":{"dispatch":"Netherlands","dest":"Germany","cust":"Germany","type":"B2B","vies":"unchecked","value":"low"},"expect":{"code":"0% Intra-Community Supply","level":"warn"}},{"id":"t17","label":"NL stock to Germany, French customer","inp":{"dispatch":"Netherlands","dest":"Germany","cust":"France","type":"B2B","vies":"valid","value":"low"},"expect":{"code":"0% Intra-Community Supply"}},{"id":"t18","label":"French stock to Italian business","inp":{"dispatch":"France","dest":"Italy","cust":"Italy","type":"B2B","vies":"valid","value":"low"},"expect":{"code":"0% EU Triangulation","level":"ok","entity":"NL"}},{"id":"t19","label":"French stock to Italy, Spanish customer","inp":{"dispatch":"France","dest":"Italy","cust":"Spain","type":"B2B","vies":"valid","value":"low"},"expect":{"code":"0% EU Triangulation"}},{"id":"t20","label":"German stock to German business","inp":{"dispatch":"Germany","dest":"Germany","cust":"Germany","type":"B2B","vies":"unchecked","value":"low"},"expect":{"code":"REROUTE VIA NL REQUIRED","level":"block"}},{"id":"t21","label":"German stock to German consumer","inp":{"dispatch":"Germany","dest":"Germany","cust":"Germany","type":"B2C","vies":"unchecked","value":"low"},"expect":{"code":"REROUTE VIA NL REQUIRED","level":"block"}},{"id":"t22","label":"NL stock to Germany, US customer, no EU VAT no.","inp":{"dispatch":"Netherlands","dest":"Germany","cust":"ROW","type":"B2B","vies":"unchecked","value":"low"},"expect":{"code":"OSS Destination Rate","rate":19}},{"id":"t23","label":"French stock to Spain, UK customer with verified EU VAT no.","inp":{"dispatch":"France","dest":"Spain","cust":"UK","type":"B2B","vies":"valid","value":"low"},"expect":{"code":"0% EU Triangulation"}},{"id":"t24","label":"NL stock to German business, VAT no. invalid","inp":{"dispatch":"Netherlands","dest":"Germany","cust":"Germany","type":"B2B","vies":"invalid","value":"low"},"expect":{"code":"OSS Destination Rate","rate":19}},{"id":"t25","label":"NL stock to German consumer","inp":{"dispatch":"Netherlands","dest":"Germany","cust":"Germany","type":"B2C","vies":"unchecked","value":"low"},"expect":{"code":"OSS Destination Rate","rate":19,"entity":"NL"}},{"id":"t26","label":"NL stock to Portuguese consumer","inp":{"dispatch":"Netherlands","dest":"Portugal","cust":"Portugal","type":"B2C","vies":"unchecked","value":"low"},"expect":{"code":"OSS Destination Rate","rate":23}},{"id":"t27","label":"UK stock to Dutch business","inp":{"dispatch":"UK","dest":"Netherlands","cust":"Netherlands","type":"B2B","vies":"unchecked","value":"low"},"expect":{"code":"0% UK Export"}}]'::jsonb, 'Starter rules: Miranda''s EU VAT Calculator v3 with her answers up to 14 Oct 2026 and the formula issues fixed.', now(), 'usr_demo_admin', 'usr_demo_admin'),
  ('rs_demo_draft', 'org_demo', 'draft', NULL, '[{"id":"r-reroute","name":"Reroute: same-country sale from other EU stock","note":"Matches spreadsheet v3. Miranda confirmed (14 Oct) this blocks consumer sales too, as the client has no local VAT registration.","signoff":false,"when":{"origin":["OTHER"],"dispatchIsDest":true},"then":{"warning":"Stock in {dispatch} can''t be sold for delivery within {dispatch}: the client has no VAT registration there. Move the goods through the Netherlands warehouse first.","needsVat":false,"level":"block","entity":"","code":"REROUTE VIA NL REQUIRED","rate":{"kind":"none"},"invoice":"DO NOT INVOICE: Goods must be rerouted through the Netherlands warehouse to comply with local storage tax rules."}},{"id":"r-export","name":"Export outside the UK and EU","note":"Matches spreadsheet v3.","signoff":false,"when":{"destZone":["ROW"]},"then":{"warning":"CRITICAL EXPORT CHECK: Fulfill this order from UK stock where possible to avoid EU paper registration customs blockages.","needsVat":false,"level":"ok","entity":"UK","code":"0% Export","rate":{"kind":"fixed","value":0},"invoice":"Zero-Rated Export – Out of Scope of UK/EU VAT. Proof of export required for tax records."}},{"id":"r-uk-domestic","name":"UK stock delivered in the UK","note":"Matches spreadsheet v3. The client is established in the UK.","signoff":false,"when":{"origin":["UK"],"destZone":["UK"]},"then":{"warning":"Standard UK Domestic transaction rules apply.","needsVat":false,"level":"ok","entity":"UK","code":"20% UK VAT","rate":{"kind":"dest"},"invoice":"Standard Domestic Supply - UK VAT charged at the statutory rate."}},{"id":"r-eu-uk","name":"EU stock delivered in the UK","note":"Matches spreadsheet v3. Miranda (14 Oct): the client owns the goods on import into the UK, so this is a UK sale. Open point: assumes the client always imports the goods itself.","signoff":true,"when":{"origin":["NL","OTHER"],"destZone":["UK"]},"then":{"warning":"NOTE: Import VAT and customs clearance are