ch consumer","inp":{"dispatch":"France","dest":"Netherlands","cust":"Netherlands","type":"B2C","vies":"unchecked","value":"low"},"expect":{"code":"OSS Destination Rate","rate":21}},{"id":"t15","label":"NL stock to German business, VAT no. verified","inp":{"dispatch":"Netherlands","dest":"Germany","cust":"Germany","type":"B2B","vies":"valid","value":"low"},"expect":{"code":"0% Intra-Community Supply","level":"ok","entity":"NL"}},{"id":"t16","label":"NL stock to German business, VAT no. not checked","inp":{"dispatch":"Netherlands","dest":"Germany","cust":"Germany","type":"B2B","vies":"unchecked","value":"low"},"expect":{"code":"0% Intra-Community Supply","level":"warn"}},{"id":"t17","label":"NL stock to Germany, French customer","inp":{"dispatch":"Netherlands","dest":"Germany","cust":"France","type":"B2B","vies":"valid","value":"low"},"expect":{"code":"0% Intra-Community Supply"}},{"id":"t18","label":"French stock to Italian business","inp":{"dispatch":"France","dest":"Italy","cust":"Italy","type":"B2B","vies":"valid","value":"low"},"expect":{"code":"0% EU Triangulation","level":"ok","entity":"NL"}},{"id":"t19","label":"French stock to Italy, Spanish customer","inp":{"dispatch":"France","dest":"Italy","cust":"Spain","type":"B2B","vies":"valid","value":"low"},"expect":{"code":"0% EU Triangulation"}},{"id":"t20","label":"German stock to German business","inp":{"dispatch":"Germany","dest":"Germany","cust":"Germany","type":"B2B","vies":"unchecked","value":"low"},"expect":{"code":"REROUTE VIA NL REQUIRED","level":"block"}},{"id":"t21","label":"German stock to German consumer","inp":{"dispatch":"Germany","dest":"Germany","cust":"Germany","type":"B2C","vies":"unchecked","value":"low"},"expect":{"code":"REROUTE VIA NL REQUIRED","level":"block"}},{"id":"t22","label":"NL stock to Germany, US customer, no EU VAT no.","inp":{"dispatch":"Netherlands","dest":"Germany","cust":"ROW","type":"B2B","vies":"unchecked","value":"low"},"expect":{"code":"OSS Destination Rate","rate":19}},{"i